body{font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;line-height:1.75;color:#1f2328;max-width:920px;margin:0 auto;padding:40px 32px;background:#fff;}
h1{font-size:28px;border-bottom:3px solid #d946ef;padding-bottom:12px;color:#111;}
h2{font-size:22px;margin-top:38px;padding-left:12px;border-left:5px solid #d946ef;color:#111;}
h3{font-size:17px;margin-top:26px;color:#7c3aed;}
table{border-collapse:collapse;width:100%;margin:16px 0;font-size:14px;}
th{background:#fdf4ff;border:1px solid #e5e7eb;padding:9px 12px;text-align:left;font-weight:600;}
td{border:1px solid #e5e7eb;padding:9px 12px;vertical-align:top;}
tr:nth-child(even) td{background:#fafafa;}
blockquote{border-left:4px solid #f0abfc;background:#fdf4ff;margin:14px 0;padding:10px 16px;color:#4a5568;}
code{background:#f3f4f6;padding:2px 6px;border-radius:4px;font-size:13px;}
hr{border:none;border-top:1px solid #e5e7eb;margin:32px 0;}
strong{color:#be185d;}
ul,ol{padding-left:24px;}
li{margin:5px 0;}
